          const r=await fetch(API,{method:'POST',body:b,cache:'no-store',signal:ctrl.signal,keepalive:false});
          const raw=await r.text();let d;
          try{d=JSON.parse(raw)}catch(e){const err=Error('BrightAce /exec is returning HTML instead of the current JSON API. Deploy the latest backend as a new version of the SAME Web App and keep the existing /exec URL.');err.apiResponse=true;throw err}
