  function dateText(v){if(!v)return '—';if(typeof v==='number'&&isFinite(v)){if(v<1)return '—';const d=new Date(Date.UTC(1899,11,30)+Math.round(v*86400000));return d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'})}const d=new Date(v);if(isNaN(d.getTime()))return String(v);if(d.getFullYear()<1901)return '—';return d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})}
  function sessionTimeText(v){if(v===null||v===undefined||v==='')return '—';if(typeof v==='number'&&isFinite(v)){const n=((Math.round(v*1440)%1440)+1440)%1440;return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}if(typeof v==='string'&&/^\d{1,2}:\d{2}/.test(v))return v.slice(0,5).padStart(5,'0');const d=new Date(v);if(!isNaN(d.getTime())&&d.getFullYear()<1901)return d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false});return String(v)}
  function dateTimeText(v){if(!v)return '—';const d=new Date(v);return isNaN(d.getTime())?String(v):d.toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
