      root.querySelector('#baMessageSend')?.addEventListener('click',async()=>{const job=selected(),id=jobKey(job),btn=root.querySelector('#baMessageSend'),input=root.querySelector('#baMessageInput'),notice=root.querySelector('#baMessageNotice'),text=input.value.trim(),attachments=window.BrightAceComposer?.getAttachments(input)||[];if(!id||!String(job?.assignedTutor||job?.tutor||'').trim()||(!text&&!attachments.length)){notice.textContent='Select an assigned job and enter a message first.';return}const tempId='local-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),pending={id:tempId,conversationId:id,sessionId:id,sender:'student',senderName:s.name||'You',source:'work-comment',text,attachment:attachments.map(f=>({name:f.name,mimeType:f.type||'application/octet-stream',size:f.size,pending:true})),timestamp:new Date().toISOString(),status:attachments.length?'uploading':'sending'};d.messages=Array.isArray(d.messages)?d.messages:[];d.messages.push(pending);input.value='';window.BrightAceComposer?.clear(input);notice.textContent=attachments.length?'Uploading attachment(s) and sending your message…':'Sending your message…';btn.disabled=true;btn.textContent=attachments.length?'UPLOADING…':'SENDING…';draw();try{const result=await post('clientSendComment',{conversationId:id,clientSessionToken:s.clientSessionToken,clientAccessToken:s.clientAccessToken,phone:s.phone,text,attachments});const at=d.messages.findIndex(m=>m.id===tempId);const sent={...pending,id:result.messageId||tempId,attachment:result.attachment||result.attachments||null,timestamp:new Date().toISOString(),status:'sent'};if(at>=0)d.messages.splice(at,1,sent);else d.messages.push(sent);notice.textContent=attachments.length?'Uploaded and sent.':'Sent.';draw();refreshSelectedWorkMessages().catch(()=>{});}catch(e){const at=d.messages.findIndex(m=>m.id===tempId);if(at>=0)d.messages[at]={...d.messages[at],status:'failed'};draw();if(/session|expired|verify/i.test(String(e?.message||'')))notice.textContent='Your session needs to be refreshed before sending. Please reload the page or sign in again.';else notice.textContent=e.message||'Message could not be sent. Please try again.'}finally{btn.disabled=false;btn.textContent='SEND TO TUTOR'}});
      async function refreshSelectedWorkMessages(){const job=selected();if(!job||document.visibilityState==='hidden')return;const fresh=await post('clientWorkMessages',{conversationId:jobKey(job),clientSessionToken:s.clientSessionToken,clientAccessToken:s.clientAccessToken,phone:s.phone});if(!fresh?.ok)return;const otherMessages=msgs.filter(m=>String(m.conversationId||m.sessionId||'')!==String(jobKey(job)));msgs.splice(0,msgs.length,...otherMessages,...(fresh.messages||[]).map(m=>Object.assign({},m,{conversationId:jobKey(job)})));d.messages=msgs;d.documents=(Array.isArray(d.documents)?d.documents.filter(a=>String(a.conversationId||a.sessionId||'')!==String(jobKey(job))):[]).concat(fresh.documents||[]);draw()}
