      const cats=['All',...new Set(resources.map(x=>String(x.category||'General')).filter(Boolean))],grid=root.querySelector('#baResourceGrid'),search=root.querySelector('#baResourceSearch'),catEl=root.querySelector('#baResourceCats');catEl.innerHTML=cats.map((x,i)=>`<button type="button" class="${i===0?'active':''}" data-cat="${esc(x)}">${esc(x)}</button>`).join('');
      const paint=()=>{const q=search.value.trim().toLowerCase(),active=catEl.querySelector('.active')?.dataset.cat||'All',rows=resources.filter(x=>(active==='All'||String(x.category||'General')===active)&&(!q||[x.title,x.category,x.description].join(' ').toLowerCase().includes(q)));grid.innerHTML=rows.map(x=>`<article class="ba-resource-card"><div class="ba-resource-thumb">${x.thumbnailUrl?`<img src="${esc(x.thumbnailUrl)}" alt="${esc(x.title)}" loading="lazy">`:'📚'}</div><span class="ba-pill">${esc(x.category||'General')}</span><h3>${esc(x.title||'Study Resource')}</h3><p>${esc(x.description||'BrightAce academic resource.')}</p><small>${esc(x.fileName||'Resource file')} · ${x.expiresAt?`Access until ${esc(dateText(x.expiresAt))}`:'Active access'}</small><button class="btn btn-primary" data-open-resource="${esc(x.purchaseId)}">OPEN RESOURCE</button></article>`).join('')||'<div class="ba-empty">No resources match your search or category.</div>';grid.querySelectorAll('[data-open-resource]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await post('clientResourceAccess',{purchaseId:b.dataset.openResource,clientSessionToken:s.clientSessionToken,phone:s.phone,userAgent:navigator.userAgent});if(r.downloadUrl)window.open(r.downloadUrl,'_blank','noopener');else throw Error('The resource file is currently unavailable.')}catch(e){alert(e.message||'Resource could not be opened.')}finally{b.disabled=false}})};
      async function loadResourceRequests(){const list=root.querySelector('#baRRList');try{const d=await post('clientListResourceRequests',{clientSessionToken:s.clientSessionToken,phone:s.phone});const reqs=d.requests||[];list.innerHTML=reqs.map(x=>`<article class="ba-resource-card"><span class="ba-pill">${esc(x.status)}</span><h3>${esc(x.topic)}</h3><p><strong>${esc(x.category)}</strong> · Submitted ${esc(dateText(x.createdAt))}</p><p>${esc(x.objectives)}</p>${x.adminResponse?`<p><strong>BrightAce response:</strong> ${esc(x.adminResponse)}</p>`:''}${Number(x.quoteAmountUSD)>0?`<div class=\"ba-resource-quote\"><strong>Quoted price</strong><div class=\"ba-resource-quote-price\">${esc(formatMoney({amount:Number(x.quoteAmountUSD),currency:x.quoteCurrency||'USD'}))}</div><small>Payment status: ${esc(x.quotePaymentStatus||'NOT PAID')}</small></div>`:''}${x.status==='Awaiting payment'&&Number(x.quoteAmountUSD)>0&&x.quotePaymentStatus!=='PAID'?`<button type="button" class="btn btn-primary" data-pay-quote="${esc(x.requestId)}" data-email="${esc(x.clientEmail||'')}">APPROVE QUOTATION &amp; PAY SECURELY · ${esc(formatMoney({amount:Number(x.quoteAmountUSD),currency:x.quoteCurrency||'USD'}))}</button>`:''}${x.hasDelivery&&x.status==='Delivered'?`<button type="button" class="btn btn-primary" data-delivery="${esc(x.requestId)}">DOWNLOAD DELIVERED FILE</button>`:''}<small>Request ID: ${esc(x.requestId)}</small></article>`).join('')||'<div class="ba-empty">You have not submitted any resource requests yet.</div>';list.querySelectorAll('[data-delivery]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const d=await post('clientResourceDeliveryAccess',{requestId:b.dataset.delivery,clientSessionToken:s.clientSessionToken,phone:s.phone});const raw=atob(d.data),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const blob=new Blob([bytes],{type:d.mimeType||'application/octet-stream'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.fileName||'BrightAce-resource';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){alert(e.message||'Delivered file could not be downloaded.')}finally{b.disabled=false}});list.querySelectorAll('[data-pay-quote]').forEach(b=>b.onclick=async()=>{if(!confirm('Approve the quotation shown and continue to secure payment?'))return;b.disabled=true;const old=b.textContent;b.textContent='Preparing secure payment…';try{let customerEmail=String(b.dataset.email||'').trim();if(!customerEmail){customerEmail=prompt('Enter an email address for your payment receipt:')||'';if(!customerEmail.trim())throw Error('An email address is required to start payment.');}const p=await post('clientApproveResourceQuote',{requestId:b.dataset.payQuote,clientSessionToken:s.clientSessionToken,phone:s.phone,customerEmail:customerEmail.trim()});if(!p.authorizationUrl)throw Error('The payment provider did not return a checkout URL.');window.location.assign(p.authorizationUrl)}catch(e){alert(e.message||'Payment could not be started.');b.disabled=false;b.textContent=old}})}catch(e){list.innerHTML='<div class="ba-empty">Could not load your requests. Please refresh and try again.</div>'}}
      const catalog=root.querySelector('#baResourceCatalog');(async()=>{try{const catalogApi=window.BRIGHTACE_API_URL||'';if(!catalogApi)throw Error('Resource catalog endpoint is not configured.');const resp=await fetch(catalogApi+'?action=resources',{cache:'no-store'}),data=await resp.json();if(!resp.ok||!data.ok)throw Error(data.error||'Catalog unavailable');const items=(data.resources||[]).filter(x=>x.published&&x.accessLevel==='PUBLIC');catalog.innerHTML=items.map(x=>`<article class="ba-resource-card"><div class="ba-resource-thumb">${x.thumbnailUrl?`<img src="${esc(x.thumbnailUrl)}" alt="${esc(x.title)}" loading="lazy">`:'📚'}</div><span class="ba-pill">${esc(x.category||'Learning resource')}</span><h3>${esc(x.title)}</h3><p>${esc(x.description||'BrightAce learning material.')}</p><div class="ba-resource-price">${esc(formatMoney({amount:Number(x.priceUSD||0),currency:'USD'}))}</div><a class="btn btn-primary" href="resource-checkout.html?resource=${encodeURIComponent(x.resourceId)}">VIEW &amp; BUY</a></article>`).join('')||'<div class="ba-empty">No approved paid resources are published yet. You can submit a custom request below.</div>'}catch(err){catalog.innerHTML='<div class="ba-empty">Approved resources could not be loaded. Please refresh or contact BrightAce support.</div>'}})();const form=root.querySelector('#baResourceRequestForm'),rrNotice=root.querySelector('#baRRNotice');form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button[type=submit]');btn.disabled=true;rrNotice.hidden=false;rrNotice.textContent='Submitting your request…';rrNotice.className='chat-notice';try{const d=await post('clientCreateResourceRequest',{clientSessionToken:s.clientSessionToken,phone:s.phone,category:root.querySelector('#baRRCategory').value,topic:root.querySelector('#baRRTopic').value.trim(),objectives:root.querySelector('#baRRObjectives').value.trim(),details:root.querySelector('#baRRDetails').value.trim()});rrNotice.textContent='Request received. Your request ID is '+d.request.requestId+'. You can follow its status below.';rrNotice.className='chat-notice success';form.reset();await loadResourceRequests()}catch(err){rrNotice.textContent=err.message||'Request could not be submitted. Please try again.';rrNotice.className='chat-notice error'}finally{btn.disabled=false}};root.querySelector('#baRRRefresh').onclick=loadResourceRequests;
